(()=>{'use strict';if(document.body.dataset.siteKind!=='equipment')return;const panel=document.getElementById('reviewAdminPanel'),list=document.getElementById('reviewAdminList'),notice=document.getElementById('reviewAdminNotice');panel.hidden=false;
async function load(){notice.textContent='در حال دریافت…';try{const response=await fetch('/api/rental/storefront/reviews'),data=await response.json();if(!response.ok)throw Error();list.replaceChildren();for(const row of data.reviews){const card=document.createElement('article'),name=document.createElement('b'),text=document.createElement('p'),state=document.createElement('small');name.textContent=row.author_name+' — '+Number(row.rating).toLocaleString('fa-IR')+' از ۵';text.textContent=row.body;state.textContent=({pending:'در انتظار تأیید',approved:'منتشرشده',rejected:'ردشده'})[row.status];card.append(name,text,state);for(const [status,title]of [['approved','تأیید و نمایش'],['rejected','رد و عدم نمایش']]){const button=document.createElement('button');button.type='button';button.textContent=title;button.disabled=row.status===status;button.onclick=async()=>{for(const b of card.querySelectorAll('button'))b.disabled=true;try{const response=await fetch('/api/rental/storefront/reviews/'+row.id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status})});if(!response.ok)throw Error();await load();}catch{notice.textContent='ثبت وضعیت انجام نشد؛ دوباره تلاش کنید.';for(const b of card.querySelectorAll('button'))b.disabled=false;}};card.append(button);}list.append(card);}notice.textContent=data.reviews.length?'نظرها فقط با تأیید شما نمایش داده می‌شوند.':'هنوز نظری ثبت نشده است.';}catch{notice.textContent='دریافت نظرها انجام نشد. برای تلاش دوباره به‌روزرسانی را بزنید.';}}
document.getElementById('refreshSiteReviews').onclick=load;load();})();
